      || CASE WHEN I18NID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(I18NID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(I18NID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END
