  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END
      || CASE WHEN TABLENAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(TABLENAME)||':'||TABLENAME||';' END
      || CASE WHEN MASTERTABLENAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(MASTERTABLENAME)||':'||MASTERTABLENAME||';' END
      || CASE WHEN REFERCOLUMN IS NULL THEN 'N;' ELSE 'V'||LENGTH(REFERCOLUMN)||':'||REFERCOLUMN||';' END AS SIGNATURE FROM T_CORE_TABLE_HIERARCHY) LOOP
