BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, ID,MENUNAME,PARENTID,ORDERNO,MENUINITNAME,ICON,TODOICON,I18NCODE,RESOURCEID,RESOURCENAME,BPID,RESOURCEPATH,MENUPARAM,HREF FROM T_CORE_MENU) LOOP
