DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(ID)||':'||ID||';' END
      || CASE WHEN PAGESTYLE IS NULL THEN 'N;' ELSE 'V'||LENGTH(PAGESTYLE)||':'||PAGESTYLE||';' END
      || CASE WHEN PAGESKIN IS NULL THEN 'N;' ELSE 'V'||LENGTH(PAGESKIN)||':'||PAGESKIN||';' END
      || CASE WHEN SPECIALCHARACTER IS NULL THEN 'N;' ELSE 'V'||LENGTH(SPECIALCHARACTER)||':'||SPECIALCHARACTER||';' END
      || CASE WHEN TODOVOICEPROMPT IS NULL THEN 'N;' ELSE 'V'||LENGTH(TODOVOICEPROMPT)||':'||TODOVOICEPROMPT||';' END
      || CASE WHEN HELPMANUALOPERATION IS NULL THEN 'N;' ELSE 'V'||LENGTH(HELPMANUALOPERATION)||':'||HELPMANUALOPERATION||';' END
      || CASE WHEN ROLLINGNOTICE IS NULL THEN 'N;' ELSE 'V'||LENGTH(ROLLINGNOTICE)||':'||ROLLINGNOTICE||';' END
      || CASE WHEN NOTIFICATION IS NULL THEN 'N;' ELSE 'V'||LENGTH(NOTIFICATION)||':'||NOTIFICATION||';' END
      || CASE WHEN NOTIFICATIONAUDIO IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(NOTIFICATIONAUDIO,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(NOTIFICATIONAUDIO,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END
      || CASE WHEN VERSION IS NULL THEN 'N;' ELSE 'V'||LENGTH(VERSION)||':'||VERSION||';' END
      || CASE WHEN FILEOPERATIONLOG IS NULL THEN 'N;' ELSE 'V'||LENGTH(FILEOPERATIONLOG)||':'||FILEOPERATIONLOG||';' END
      || CASE WHEN IEACCESSTIP IS NULL THEN 'N;' ELSE 'V'||LENGTH(IEACCESSTIP)||':'||IEACCESSTIP||';' END
      || CASE WHEN FULLTEXTSEARCHRESULT IS NULL THEN 'N;' ELSE 'V'||LENGTH(FULLTEXTSEARCHRESULT)||':'||FULLTEXTSEARCHRESULT||';' END
      || CASE WHEN SPEEDTESTPERIOD IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(SPEEDTESTPERIOD,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(SPEEDTESTPERIOD,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END AS SIGNATURE FROM T_CORE_SYSTEM_CONFIG) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
  IF actual.COUNT <> 1 THEN RAISE_APPLICATION_ERROR(-20121, 'Technical bootstrap row count differs: T_CORE_SYSTEM_CONFIG'); END IF;
  IF NOT actual.EXISTS('system-config') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_SYSTEM_CONFIG'); END IF;
  IF actual('system-config') <>
    'V13:system-config;V6:xialan;V7:#00AC84;V1:1;V1:0;V4:view;V1:0;V1:1;N;V6:14.1.5;V1:0;V1:0;V15:previewDownload;V3:180;'
     THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_SYSTEM_CONFIG'); END IF;
END;
