DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(ID)||':'||ID||';' END
      || CASE WHEN CODECLASSNAME IS NULL THEN 'N;' ELSE 'V'||LENGTH(CODECLASSNAME)||':'||CODECLASSNAME||';' END
      || CASE WHEN ORDERNO IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ORDERNO,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END AS SIGNATURE FROM T_CORE_CODE_CLASS) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
  IF actual.COUNT <> 2 THEN RAISE_APPLICATION_ERROR(-20121, 'Technical bootstrap row count differs: T_CORE_CODE_CLASS'); END IF;
  IF NOT actual.EXISTS('biz') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_CODE_CLASS'); END IF;
  IF actual('biz') <>
    'V3:biz;V4:业务编码;V1:0;'
     THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_CODE_CLASS'); END IF;
  IF NOT actual.EXISTS('sys') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_CODE_CLASS'); END IF;
  IF actual('sys') <>
    'V3:sys;V4:系统编码;V1:0;'
     THEN RAISE_APPLICATION_ERROR(-20122, 'Technical bootstrap row differs: T_CORE_CODE_CLASS'); END IF;
END;
