DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  SELECT COUNT(*) INTO oversized FROM T_CORE_CODE WHERE DBMS_LOB.GETLENGTH(CODENAME)>1000;
  IF oversized <> 0 THEN RAISE_APPLICATION_ERROR(-20123, 'Technical bootstrap text exceeds reviewed capacity.'); END IF;
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN ID IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR(ID,'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END
      || CASE WHEN CODE IS NULL THEN 'N;' ELSE 'V'||LENGTH(CODE)||':'||CODE||';' END
      || CASE WHEN CODENAME IS NULL THEN 'N;' ELSE 'V'||DBMS_LOB.GETLENGTH(CODENAME)||':'||DBMS_LOB.SUBSTR(CODENAME,1000,1)||';' END
      || CASE WHEN CODECATEGORYID IS NULL THEN 'N;' ELSE 'V'||LENGTH(CODECATEGORYID)||':'||CODECATEGORYID||';' END
