  actual row_map;
  oversized NUMBER;
BEGIN
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN "ID" IS NULL THEN 'N;' ELSE 'V'||LENGTH(TO_CHAR("ID",'TM9','NLS_NUMERIC_CHARACTERS=''.,'''))||':'||TO_CHAR("ID",'TM9','NLS_NUMERIC_CHARACTERS=''.,''')||';' END
      || CASE WHEN "CONFIGID" IS NULL THEN 'N;' ELSE 'V'||LENGTH("CONFIGID")||':'||"CONFIGID"||';' END
      || CASE WHEN "COLUMNID" IS NULL THEN 'N;' ELSE 'V'||LENGTH("COLUMNID")||':'||"COLUMNID"||';' END
      || CASE WHEN "AUDITTRAIL" IS NULL THEN 'N;' ELSE 'V'||LENGTH("AUDITTRAIL")||':'||"AUDITTRAIL"||';' END AS SIGNATURE FROM T_CORE_AT_CONFIG_LINE) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
