DECLARE
  TYPE row_map IS TABLE OF VARCHAR2(32767) INDEX BY VARCHAR2(128);
  actual row_map;
  oversized NUMBER;
BEGIN
  SELECT COUNT(*) INTO oversized FROM T_CORE_AUDIT_CONFIG WHERE DBMS_LOB.GETLENGTH(SELECTDESCSQL)>1000 OR DBMS_LOB.GETLENGTH(SELECTPARENTSQL)>1000;
  IF oversized <> 0 THEN RAISE_APPLICATION_ERROR(-20123, 'Technical bootstrap text exceeds reviewed capacity.'); END IF;
  FOR r IN (SELECT TO_CHAR(ID) AS ROW_ID, CASE WHEN "ID" IS NULL THEN 'N;' ELSE 'V'||LENGTH("ID")||':'||"ID"||';' END
      || CASE WHEN "NAME" IS NULL THEN 'N;' ELSE 'V'||LENGTH("NAME")||':'||"NAME"||';' END
      || CASE WHEN "CATEGORY" IS NULL THEN 'N;' ELSE 'V'||LENGTH("CATEGORY")||':'||"CATEGORY"||';' END
      || CASE WHEN "SELECTDESCSQL" IS NULL THEN 'N;' ELSE 'V'||DBMS_LOB.GETLENGTH("SELECTDESCSQL")||':'||DBMS_LOB.SUBSTR("SELECTDESCSQL",1000,1)||';' END
      || CASE WHEN "SELECTPARENTSQL" IS NULL THEN 'N;' ELSE 'V'||DBMS_LOB.GETLENGTH("SELECTPARENTSQL")||':'||DBMS_LOB.SUBSTR("SELECTPARENTSQL",1000,1)||';' END
      || CASE WHEN "AUDITABLE" IS NULL THEN 'N;' ELSE 'V'||LENGTH("AUDITABLE")||':'||"AUDITABLE"||';' END AS SIGNATURE FROM T_CORE_AUDIT_CONFIG) LOOP
    actual(r.ROW_ID) := r.SIGNATURE;
  END LOOP;
  IF actual.COUNT <> 6 THEN RAISE_APPLICATION_ERROR(-20121, 'Technical bootstrap row count differs: T_CORE_AUDIT_CONFIG'); END IF;
  IF NOT actual.EXISTS('T_EMC_BIZ_CLASS') THEN RAISE_APPLICATION_ERROR(-20122, 'Missing technical bootstrap row: T_CORE_AUDIT_CONFIG'); END IF;
